/** ReplicatedStorage.Shared.ShurikenCutscene: cutscenes as data (camera paths, look-at, FOV, timed events, letterbox, titles, skip, safe restore) and intros. Generated Luau (keep it passing tests/runtime-lint.test.ts). */
export const FX_CUTSCENE_MODULE_VERSION = 1;

export const FX_CUTSCENE_MODULE = `--!strict
-- ShurikenCutscene v1 (generated by Shuriken Studio; safe to use, don't edit).
-- Cutscenes as data: shots move the camera along Catmull-Rom or Bezier paths at even speed, looking at a
-- point, a part or a moving path, with FOV and roll curves and a handheld drift; timed events play
-- effects, sounds, animations, dialogue lines, titles, fades, shakes and signals for game code. Letterbox,
-- titles and subtitles go through the Motion module. The player can skip (button, Space/Enter, gamepad B);
-- input and the game's UI are held while it plays; the camera, controls and UI always come back, even if
-- a cutscene errors or the character dies. Client side; the server starts it for players.
--   local Cutscene = require(game.ReplicatedStorage.Shared.ShurikenCutscene)
--   Cutscene.play("BossIntro")                          -- built from effects/cutscenes/BossIntro.cutscene.json
--   Cutscene.play({ shots = { ... }, events = { ... } })   -- or a table written in code
--   Cutscene.intro({ from = Vector3.new(0, 80, 120), title = "THE ARENA" })  -- establishing shot into play
--   Cutscene.onSignal("OpenGate", function() ... end)   -- events { at = 3, signal = "OpenGate" }
--   Cutscene.play("BossIntro", { players = { player } })   -- on the server: relayed to those players
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local StarterGui = game:GetService("StarterGui")
local ContextActionService = game:GetService("ContextActionService")
local Curves = require(script.Parent.ShurikenCurves)

local Cutscene = {}

export type Handle = { stop: () -> (), finished: () -> boolean, wait: () -> () }
export type PlayOptions = {
	players: { Player }?, -- server: who sees it (default everyone)
	onEnded: ((skipped: boolean) -> ())?,
}
export type IntroOptions = {
	from: (Vector3 | CFrame | { Vector3 })?, -- where the camera starts (or a path of points); default high behind the spawn
	seconds: number?, -- default 3.5
	title: string?,
	subtitle: string?,
	letterbox: number?, -- default 0.1
	skippable: boolean?,
}

local warned: { [string]: boolean } = {}
local function warnOnce(key: string, message: string)
	if not warned[key] then
		warned[key] = true
		warn("[ShurikenCutscene] " .. message)
	end
end

local loaded: { [string]: any } = {}
local function sibling(name: string): any
	local got = loaded[name]
	if got ~= nil then
		return if got == false then nil else got
	end
	local m = script.Parent and script.Parent:FindFirstChild(name)
	if m and m:IsA("ModuleScript") then
		local ok, mod = pcall(require, m)
		if ok then
			loaded[name] = mod
			return mod
		end
	end
	loaded[name] = false
	return nil
end

local function num(v: any, default: number): number
	return if typeof(v) == "number" then v else default
end

local function vec(v: any): Vector3?
	if typeof(v) == "Vector3" then
		return v
	elseif typeof(v) == "CFrame" then
		return v.Position
	elseif typeof(v) == "table" and typeof(v[1]) == "number" then
		return Vector3.new(v[1], num(v[2], 0), num(v[3], 0))
	end
	return nil
end

-- "Workspace.Arena.Gate" -> the instance (nil when missing or not streamed in yet).
local function resolve(path: string): Instance?
	local node: Instance? = game
	for part in string.gmatch(path, "[^%.]+") do
		if not node then
			return nil
		end
		if node == game then
			local ok, service = pcall(function()
				return game:GetService(part)
			end)
			node = if ok then service else game:FindFirstChild(part)
		else
			node = node:FindFirstChild(part)
		end
	end
	return if node == game then nil else node
end

local function character(): Model?
	local player = Players.LocalPlayer
	return player and player.Character
end

-- A target the camera looks at or an event plays at: a point, "player", an instance path, or a part.
local function pointOf(target: any): Vector3?
	local direct = vec(target)
	if direct then
		return direct
	end
	local inst: Instance? = nil
	if target == "player" then
		inst = character()
	elseif typeof(target) == "string" then
		inst = resolve(target)
	elseif typeof(target) == "Instance" then
		inst = target
	end
	if not inst then
		return nil
	end
	if inst:IsA("Model") then
		local head = inst:FindFirstChild("Head")
		if head and head:IsA("BasePart") then
			return head.Position
		end
		return inst:GetPivot().Position
	elseif inst:IsA("BasePart") then
		return inst.Position
	elseif inst:IsA("Attachment") then
		return inst.WorldPosition
	end
	return nil
end

local function pathOf(spec: any): Curves.Path?
	local raw = if typeof(spec) == "table" and spec.points then spec.points else spec
	if typeof(raw) ~= "table" then
		local p = pointOf(raw)
		return if p then Curves.polyline({ p, p }) else nil
	end
	local pts: { Vector3 } = {}
	for _, p in raw do
		local v = pointOf(p)
		if v then
			table.insert(pts, v)
		end
	end
	if #pts == 0 then
		return nil
	end
	local kind = if typeof(spec) == "table" then spec.kind else nil
	if kind == "bezier" and #pts == 4 then
		return Curves.bezier(pts[1], pts[2], pts[3], pts[4])
	elseif kind == "linear" or #pts < 3 then
		return Curves.polyline(pts)
	end
	return Curves.catmullRom(pts)
end

------------------------------------------------------------------------------------------- Data
-- The data (see effects/cutscenes/*.cutscene.json):
-- { duration?, letterbox? (0..0.2 of the screen per bar, default 0.11), skippable? (true), skipAfter? (0.6),
--   hideUi? (true), shots = { { at, duration, camera = { points = {{x,y,z}, ...}, kind = "catmullRom" |
--   "bezier" | "linear", ease }, lookAt = {x,y,z} | {points = ...} | "player" | "Workspace.Path",
--   fov = curve, roll = curve, drift = studs } }, events = { { at, effect | sound | animation + rig | line +
--   speaker | title + subtitle | fade | shake | signal, ... } } }
local function cutsceneData(nameOrData: any): any
	if typeof(nameOrData) == "table" then
		return nameOrData
	end
	local root = ReplicatedStorage:FindFirstChild("ShurikenEffects")
	local folder = root and root:FindFirstChild("Cutscenes")
	local value = folder and folder:FindFirstChild(tostring(nameOrData))
	if value and value:IsA("StringValue") then
		local ok, data = pcall(function()
			return HttpService:JSONDecode(value.Value)
		end)
		if ok then
			return data
		end
	end
	warnOnce("missing:" .. tostring(nameOrData), "no cutscene named " .. tostring(nameOrData) .. " (vfx_cutscene builds them)")
	return nil
end

local function lengthOf(data: any): number
	local length = num(data.duration, 0)
	for _, shot in data.shots or {} do
		length = math.max(length, num(shot.at, 0) + num(shot.duration, 3))
	end
	for _, e in data.events or {} do
		length = math.max(length, num(e.at, 0) + num(e.seconds, 0))
	end
	return length
end

------------------------------------------------------------------------------------------- UI (via Motion)
type Ui = { gui: ScreenGui, top: Frame, bottom: Frame, subtitle: TextLabel, fade: Frame, skip: TextButton }

-- Type in the style of the UI showpieces (skill roblox-ui-showpieces): a display face for titles with a dark
-- outline, the UI's body face for subtitles. Cutscene.setFonts puts the game's own faces in.
local fonts = { display = Font.fromEnum(Enum.Font.Oswald), body = Font.fromEnum(Enum.Font.BuilderSans), bold = Font.fromEnum(Enum.Font.BuilderSansBold) }

--- The game's display face (titles) and body face (subtitles, the skip button).
function Cutscene.setFonts(display: Font?, body: Font?, bold: Font?)
	fonts.display = display or fonts.display
	fonts.body = body or fonts.body
	fonts.bold = bold or fonts.bold
end

local function motion(): any
	local M = sibling("Motion")
	if not M then
		warnOnce("motion", "needs the Motion module beside it for letterbox, titles and subtitles (vfx_runtime adds it)")
	end
	return M
end

local function makeUi(letterbox: number): Ui?
	local player = Players.LocalPlayer
	local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
	if not playerGui then
		return nil
	end
	local gui = Instance.new("ScreenGui")
	gui.Name = "ShurikenCutscene"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	pcall(function()
		gui.ScreenInsets = Enum.ScreenInsets.None
	end)
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.DisplayOrder = 95
	local function bar(anchorY: number): Frame
		local f = Instance.new("Frame")
		f.BorderSizePixel = 0
		f.BackgroundColor3 = Color3.new(0, 0, 0)
		f.AnchorPoint = Vector2.new(0, anchorY)
		f.Position = UDim2.fromScale(0, anchorY)
		f.Size = UDim2.fromScale(1, 0)
		f.Parent = gui
		return f
	end
	local top, bottom = bar(0), bar(1)
	local subtitle = Instance.new("TextLabel")
	subtitle.Name = "Subtitle"
	subtitle.AnchorPoint = Vector2.new(0.5, 1)
	subtitle.Position = UDim2.new(0.5, 0, 1, -12)
	subtitle.Size = UDim2.fromScale(0.8, math.max(letterbox, 0.08) * 0.7)
	subtitle.BackgroundTransparency = 1
	subtitle.TextScaled = true
	subtitle.TextWrapped = true
	subtitle.RichText = true
	subtitle.FontFace = fonts.body
	subtitle.TextColor3 = Color3.new(1, 1, 1)
	subtitle.TextStrokeTransparency = 0.5
	subtitle.TextTransparency = 1
	subtitle.Text = ""
	local limit = Instance.new("UITextSizeConstraint")
	limit.MaxTextSize = 30
	limit.MinTextSize = 14
	limit.Parent = subtitle
	subtitle.ZIndex = 3
	subtitle.Parent = gui
	local fade = Instance.new("Frame")
	fade.Name = "Fade"
	fade.BorderSizePixel = 0
	fade.Size = UDim2.fromScale(1, 1)
	fade.BackgroundColor3 = Color3.new(0, 0, 0)
	fade.BackgroundTransparency = 1
	fade.ZIndex = 2
	fade.Parent = gui
	local skip = Instance.new("TextButton")
	skip.Name = "Skip"
	skip.AnchorPoint = Vector2.new(1, 1)
	skip.Position = UDim2.new(1, -24, 1, -16)
	skip.Size = UDim2.fromOffset(110, 44)
	skip.BackgroundColor3 = Color3.new(0, 0, 0)
	skip.BackgroundTransparency = 0.4
	skip.FontFace = fonts.bold
	skip.TextSize = 18
	skip.TextColor3 = Color3.new(1, 1, 1)
	skip.Text = "Skip  >>"
	skip.Visible = false
	skip.ZIndex = 4
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 10)
	corner.Parent = skip
	skip.Parent = gui
	gui.Parent = playerGui
	local M = motion()
	if M and letterbox > 0 then
		local info = M.T.slideIn or TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		M.tween(top, info, { Size = UDim2.fromScale(1, letterbox) })
		M.tween(bottom, info, { Size = UDim2.fromScale(1, letterbox) })
	end
	return { gui = gui, top = top, bottom = bottom, subtitle = subtitle, fade = fade, skip = skip }
end

local function showTitle(ui: Ui, title: string, sub: string?, seconds: number)
	local M = motion()
	if not M then
		return
	end
	local holder = Instance.new("Frame")
	holder.AnchorPoint = Vector2.new(0.5, 0.5)
	holder.Position = UDim2.fromScale(0.5, 0.45)
	holder.Size = UDim2.fromScale(0.8, 0.2)
	holder.BackgroundTransparency = 1
	holder.ZIndex = 3
	local layout = Instance.new("UIListLayout")
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	layout.VerticalAlignment = Enum.VerticalAlignment.Center
	layout.Padding = UDim.new(0, 6)
	layout.Parent = holder
	local strokes: { UIStroke } = {}
	local function line(text: string, size: number, font: Font, edge: number): TextLabel
		local l = Instance.new("TextLabel")
		l.BackgroundTransparency = 1
		l.Size = UDim2.new(1, 0, 0, size + 8)
		l.FontFace = font
		l.TextSize = size
		l.Text = text
		l.TextColor3 = Color3.new(1, 1, 1)
		l.ZIndex = 3
		local s = Instance.new("UIStroke")
		s.Color = Color3.new(0, 0, 0)
		s.Thickness = edge
		s.Transparency = 0.2
		s.Parent = l
		table.insert(strokes, s)
		l.Parent = holder
		return l
	end
	local labels = { line(title, 56, fonts.display, 3) }
	if sub and sub ~= "" then
		table.insert(labels, line(sub, 24, fonts.body, 2))
	end
	holder.Parent = ui.gui
	M.enter(labels, { from = "up", gap = 0.12 })
	task.delay(math.max(seconds - 0.4, 0.2), function()
		local out = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		for _, l in labels do
			M.tween(l, out, { TextTransparency = 1 })
		end
		for _, s in strokes do
			M.tween(s, out, { Transparency = 1 })
		end
		task.delay(0.45, function()
			holder:Destroy()
		end)
	end)
end

local subtitleSerial = 0
local function showLine(ui: Ui, text: string, speaker: string?, seconds: number)
	local M = motion()
	if not M then
		return
	end
	subtitleSerial += 1
	local mine = subtitleSerial
	local safe = string.gsub(string.gsub(text, "<", "&lt;"), ">", "&gt;")
	ui.subtitle.Text = if speaker and speaker ~= "" then ("<b>%s:</b> %s"):format(speaker, safe) else safe
	ui.subtitle.TextTransparency = 1
	M.tween(ui.subtitle, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { TextTransparency = 0 })
	task.delay(seconds, function()
		if subtitleSerial == mine and ui.subtitle.Parent then
			M.tween(ui.subtitle, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { TextTransparency = 1 })
		end
	end)
end

------------------------------------------------------------------------------------------- Holding the player
type Saved = {
	cameraType: Enum.CameraType,
	subject: Instance?,
	fov: number,
	core: { [Enum.CoreGuiType]: boolean },
	guis: { ScreenGui },
	controls: any,
}

local function controlsOf(): any
	local player = Players.LocalPlayer
	local scripts = player and player:FindFirstChild("PlayerScripts")
	local module = scripts and scripts:FindFirstChild("PlayerModule")
	if module and module:IsA("ModuleScript") then
		local ok, pm = pcall(require, module)
		if ok and typeof(pm) == "table" and pm.GetControls then
			local ok2, controls = pcall(function()
				return pm:GetControls()
			end)
			if ok2 then
				return controls
			end
		end
	end
	return nil
end

local CORE_TYPES = { Enum.CoreGuiType.Backpack, Enum.CoreGuiType.PlayerList, Enum.CoreGuiType.Health, Enum.CoreGuiType.EmotesMenu, Enum.CoreGuiType.Chat }
local BLOCK = "ShurikenCutsceneBlock"
local SKIP = "ShurikenCutsceneSkip"

local function hold(hideUi: boolean, blockInput: boolean, ownGui: ScreenGui?): Saved
	local cam = workspace.CurrentCamera
	local saved: Saved = { cameraType = cam.CameraType, subject = cam.CameraSubject, fov = cam.FieldOfView, core = {}, guis = {}, controls = nil }
	if hideUi then
		for _, t in CORE_TYPES do
			local ok, on = pcall(function()
				return StarterGui:GetCoreGuiEnabled(t)
			end)
			if ok and on then
				saved.core[t] = true
				pcall(function()
					StarterGui:SetCoreGuiEnabled(t, false)
				end)
			end
		end
		local player = Players.LocalPlayer
		local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
		if playerGui then
			for _, g in playerGui:GetChildren() do
				if g:IsA("ScreenGui") and g.Enabled and g ~= ownGui and not string.match(g.Name, "^Motion") then
					g.Enabled = false
					table.insert(saved.guis, g)
				end
			end
		end
	end
	if blockInput then
		local controls = controlsOf()
		if controls then
			pcall(function()
				controls:Disable()
			end)
			saved.controls = controls
		end
		-- Sink the game's own actions while it plays (GUI buttons, like Skip, still work).
		ContextActionService:BindActionAtPriority(BLOCK, function()
			return Enum.ContextActionResult.Sink
		end, false, Enum.ContextActionPriority.High.Value + 100, Enum.UserInputType.MouseButton1, Enum.UserInputType.MouseButton2, Enum.KeyCode.ButtonR2, Enum.KeyCode.ButtonL2, Enum.KeyCode.ButtonX, Enum.KeyCode.ButtonY, Enum.KeyCode.E, Enum.KeyCode.F, Enum.KeyCode.Q, Enum.KeyCode.R)
	end
	cam.CameraType = Enum.CameraType.Scriptable
	return saved
end

local function release(saved: Saved)
	local cam = workspace.CurrentCamera
	pcall(function()
		ContextActionService:UnbindAction(BLOCK)
		ContextActionService:UnbindAction(SKIP)
	end)
	local char = character()
	local humanoid = char and char:FindFirstChildOfClass("Humanoid")
	-- A respawned character: follow the new one, not the old (destroyed) subject.
	local subject = if saved.subject and saved.subject.Parent then saved.subject else humanoid
	cam.CameraType = if saved.cameraType == Enum.CameraType.Scriptable then Enum.CameraType.Custom else saved.cameraType
	if subject then
		cam.CameraSubject = subject
	end
	cam.FieldOfView = saved.fov
	for t in saved.core do
		pcall(function()
			StarterGui:SetCoreGuiEnabled(t, true)
		end)
	end
	for _, g in saved.guis do
		if g.Parent then
			g.Enabled = true
		end
	end
	if saved.controls then
		pcall(function()
			saved.controls:Enable()
		end)
	end
end

------------------------------------------------------------------------------------------- Playing
local current: { stop: (skipped: boolean) -> () }? = nil
local signals: { [string]: { (any) -> () } } = {}

--- Game code reacts to a cutscene's { at = 3, signal = "OpenGate" } events (and to skipped ones with
--- always = true). Returns a function that disconnects it.
function Cutscene.onSignal(name: string, fn: (any) -> ()): () -> ()
	local list = signals[name] or {}
	signals[name] = list
	table.insert(list, fn)
	return function()
		local i = table.find(list, fn)
		if i then
			table.remove(list, i)
		end
	end
end

local function fire(name: string, payload: any)
	local list: { (any) -> () } = signals[name] or {}
	for _, fn in list do
		task.spawn(fn, payload)
	end
end

--- Whether a cutscene is playing (game input handlers can ignore input while it is).
function Cutscene.playing(): boolean
	return current ~= nil
end

--- Stops the cutscene playing now (as if skipped).
function Cutscene.stop()
	local c = current
	if c then
		c.stop(true)
	end
end

local function runEvent(e: any, ui: Ui?)
	local Effects = sibling("ShurikenEffects")
	if e.effect and Effects then
		local where = pointOf(e.where or "player")
		if where then
			Effects.play(e.effect, if e.facing then CFrame.lookAt(where, where + (vec(e.facing) or Vector3.zAxis)) else where, { force = true, scale = e.scale })
		end
	end
	if e.sound then
		local Audio = sibling("ShurikenAudio")
		if Audio and Audio.play then
			pcall(Audio.play, e.sound, if e.where then pointOf(e.where) else nil)
		end
	end
	if e.animation then
		local Anims = sibling("ShurikenAnimations")
		local rig = if e.rig == "player" or e.rig == nil then character() elseif typeof(e.rig) == "string" then resolve(e.rig) else nil
		if Anims and rig then
			pcall(Anims.play, rig, e.animation)
		end
	end
	if e.shake and Effects then
		Effects.shake(num(e.shake, 1.5), num(e.seconds, 0.4))
	end
	if ui and e.line then
		showLine(ui, tostring(e.line), e.speaker, num(e.seconds, 3))
	end
	if ui and e.title then
		showTitle(ui, tostring(e.title), e.subtitle, num(e.seconds, 3))
	end
	if ui and e.fade then
		local M = motion()
		if M then
			local color = if typeof(e.color) == "string" then Color3.fromHex(e.color) else Color3.new(0, 0, 0)
			ui.fade.BackgroundColor3 = color
			M.tween(ui.fade, TweenInfo.new(num(e.seconds, 0.5), Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), { BackgroundTransparency = if e.fade == "out" then 0 else 1 })
		end
	end
	if e.signal then
		fire(tostring(e.signal), e.payload)
	end
end

--- Plays a cutscene for this player (by name, or data). Server: relays it to opts.players (default all).
function Cutscene.play(nameOrData: any, opts: PlayOptions?): Handle?
	if RunService:IsServer() and RunService:IsRunning() and not RunService:IsClient() then
		local Effects = sibling("ShurikenEffects")
		if Effects and Effects.relayCutscene then
			Effects.relayCutscene(nameOrData, opts)
		end
		return nil
	end
	local data = cutsceneData(nameOrData)
	local cam = workspace.CurrentCamera
	if not data or not cam then
		return nil
	end
	if current then
		current.stop(true)
	end
	local o: PlayOptions = opts or {}
	local length = lengthOf(data)
	local letterbox = math.clamp(num(data.letterbox, 0.11), 0, 0.25)
	local skippable = data.skippable ~= false
	local ui = makeUi(letterbox)
	local saved = hold(data.hideUi ~= false, data.blockInput ~= false, if ui then ui.gui else nil)

	-- Shots: each a path (even speed), what it looks at, FOV and roll curves.
	type Shot = { at: number, duration: number, path: Curves.Path?, look: any, lookPath: Curves.Path?, ease: (number) -> number, fov: any, roll: any, drift: number }
	local shots: { Shot } = {}
	for _, s in data.shots or {} do
		local cameraSpec = s.camera or s.path or s.from
		local lookSpec = s.lookAt
		local lookPath = if typeof(lookSpec) == "table" and lookSpec.points then pathOf(lookSpec) else nil
		table.insert(shots, {
			at = num(s.at, 0),
			duration = math.max(num(s.duration, 3), 0.05),
			path = pathOf(cameraSpec),
			look = lookSpec,
			lookPath = lookPath,
			ease = Curves.easer(if typeof(cameraSpec) == "table" and cameraSpec.ease then cameraSpec.ease else "sineInOut"),
			fov = s.fov or 70,
			roll = s.roll or 0,
			drift = num(s.drift, 0),
		})
	end
	table.sort(shots, function(a, b)
		return a.at < b.at
	end)
	local events: { any } = table.clone(data.events or {})
	table.sort(events, function(a, b)
		return num(a.at, 0) < num(b.at, 0)
	end)
	-- Ask the server to stream in what the shots look at (streaming places; best effort).
	task.spawn(function()
		local player = Players.LocalPlayer
		for _, shot in shots do
			local p = if shot.path then shot.path:at(0) else nil
			if p and player then
				pcall(function()
					player:RequestStreamAroundAsync(p, 2)
				end)
			end
		end
	end)

	local started = os.clock()
	local nextEvent = 1
	local done = false
	local seed = math.random() * 100
	local deathConnection: RBXScriptConnection? = nil
	local finishedSignal = Instance.new("BindableEvent")

	local function finish(skipped: boolean)
		if done then
			return
		end
		done = true
		RunService:UnbindFromRenderStep("ShurikenCutscene")
		if deathConnection then
			deathConnection:Disconnect()
		end
		if skipped then
			-- Events that must happen anyway (the gate opens, the boss spawns).
			while nextEvent <= #events do
				local e = events[nextEvent]
				nextEvent += 1
				if e.always and e.signal then
					fire(tostring(e.signal), e.payload)
				end
			end
		end
		release(saved)
		if ui then
			local gui = ui.gui
			local M = motion()
			if M and letterbox > 0 then
				local info = M.T.slideOut or TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				M.tween(ui.top, info, { Size = UDim2.fromScale(1, 0) })
				M.tween(ui.bottom, info, { Size = UDim2.fromScale(1, 0) })
				task.delay(0.3, function()
					gui:Destroy()
				end)
			else
				gui:Destroy()
			end
		end
		current = nil
		if o.onEnded then
			task.spawn(o.onEnded, skipped)
		end
		finishedSignal:Fire()
		task.defer(function()
			finishedSignal:Destroy()
		end)
	end

	current = { stop = finish }
	local char = character()
	local humanoid = char and char:FindFirstChildOfClass("Humanoid")
	if humanoid then
		deathConnection = humanoid.Died:Connect(function()
			finish(true)
		end)
	end

	if skippable then
		local after = num(data.skipAfter, 0.6)
		task.delay(after, function()
			if done then
				return
			end
			if ui then
				ui.skip.Visible = true
				ui.skip.Activated:Connect(function()
					finish(true)
				end)
			end
			ContextActionService:BindActionAtPriority(SKIP, function(_, state)
				if state == Enum.UserInputState.Begin then
					finish(true)
				end
				return Enum.ContextActionResult.Sink
			end, false, Enum.ContextActionPriority.High.Value + 200, Enum.KeyCode.Space, Enum.KeyCode.Return, Enum.KeyCode.ButtonB)
		end)
	end

	RunService:BindToRenderStep("ShurikenCutscene", Enum.RenderPriority.Camera.Value + 2, function()
		local ok, err = pcall(function()
			local t = os.clock() - started
			while nextEvent <= #events and num(events[nextEvent].at, 0) <= t do
				local e = events[nextEvent]
				nextEvent += 1
				local ran, problem = pcall(function(): boolean
					runEvent(e, ui)
					return true
				end)
				if not ran then
					warnOnce("event:" .. tostring(problem), "an event failed: " .. tostring(problem))
				end
			end
			-- The shot on screen: the last one that has started.
			local shot: Shot? = nil
			for _, s in shots do
				if s.at <= t then
					shot = s
				end
			end
			if shot then
				local k = math.clamp((t - shot.at) / shot.duration, 0, 1)
				local u = shot.ease(k)
				local position = if shot.path then shot.path:at(u) else cam.CFrame.Position
				if shot.drift > 0 then
					position += Curves.wobble(t, seed, shot.drift, 0.35)
				end
				local target = if shot.lookPath then shot.lookPath:at(u) else pointOf(shot.look)
				local frame: CFrame
				if target and (target - position).Magnitude > 1e-3 then
					frame = CFrame.lookAt(position, target)
				elseif shot.path then
					frame = CFrame.lookAt(position, position + shot.path:tangent(u))
				else
					frame = cam.CFrame
				end
				cam.CFrame = frame * CFrame.Angles(0, 0, math.rad(Curves.sample(shot.roll, k)))
				cam.FieldOfView = math.clamp(Curves.sample(shot.fov, k), 1, 120)
			end
			if t >= length then
				finish(false)
			end
		end)
		if not ok then
			warn("[ShurikenCutscene] stopped: " .. tostring(err))
			finish(true)
		end
	end)

	return {
		stop = function()
			finish(true)
		end,
		finished = function()
			return done
		end,
		wait = function()
			if not done then
				finishedSignal.Event:Wait()
			end
		end,
	}
end

--- A short establishing shot into gameplay: the camera sweeps from \`from\` to where the game's camera sits
--- behind the character, then hands over without a jump. Waits for the character (up to 10 s).
function Cutscene.intro(opts: IntroOptions?): Handle?
	local o: IntroOptions = opts or {}
	local player = Players.LocalPlayer
	if not player then
		return nil
	end
	local char = player.Character or player.CharacterAdded:Wait()
	local root = char:WaitForChild("HumanoidRootPart", 10)
	local cam = workspace.CurrentCamera
	if not (root and root:IsA("BasePart")) or not cam then
		return nil
	end
	task.wait() -- one frame: the game's camera settles behind the character
	local goal = cam.CFrame
	local head = root.Position + Vector3.new(0, 1.5, 0)
	local points: { Vector3 } = {}
	local from = o.from
	if typeof(from) == "table" then
		for _, p in from do
			table.insert(points, p)
		end
	elseif typeof(from) == "CFrame" then
		table.insert(points, from.Position)
	elseif typeof(from) == "Vector3" then
		table.insert(points, from)
	else
		table.insert(points, root.Position + root.CFrame.LookVector * 60 + Vector3.new(0, 45, 0))
	end
	-- A mid point that swings round toward the final view, then the game camera's own position.
	local first = points[#points]
	table.insert(points, first:Lerp(goal.Position, 0.65) + Vector3.new(0, 8, 0))
	table.insert(points, goal.Position)
	local seconds = o.seconds or 3.5
	local focus = goal.Position + goal.LookVector * (goal.Position - head).Magnitude
	local lookPoints = { { head.X, head.Y, head.Z }, { focus.X, focus.Y, focus.Z } }
	local pts = {}
	for _, p in points do
		table.insert(pts, { p.X, p.Y, p.Z })
	end
	local data = {
		letterbox = o.letterbox or 0.1,
		skippable = o.skippable ~= false,
		hideUi = true,
		shots = { { at = 0, duration = seconds, camera = { points = pts, ease = "sineInOut" }, lookAt = { points = lookPoints, kind = "linear" }, fov = { cam.FieldOfView - 10, cam.FieldOfView } } },
		events = if o.title then { { at = 0.3, title = o.title, subtitle = o.subtitle, seconds = math.min(seconds - 0.4, 3) } } else {},
	}
	return Cutscene.play(data)
end

return Cutscene
`;
